+                for (int i = 0; i < children.size(); i++) {
+                    if (nonNullExp.semanticEquals(children.get(i))) {
+                        return exp.replaceChildren(children.subList(0, i + 1));
+                    }
+                }
+            }
+            return super.nonNullify(exp, nonNullExp);
